use std::future::Future;
use std::pin::Pin;

trait Service {
    fn call(&self) -> ⟦ret_type⟧;
}

struct Echo;
impl Service for Echo {
    fn call(&self) -> Pin<Box<dyn Future<Output = i32>>> {
        ⟦body_expr⟧
    }
}

tests:
#[test]
fn calls_dyn_service() {
    let echo = Echo;
    let svc: &dyn Service = &echo;
    fn noop(_: *const ()) {}
    fn clone(p: *const ()) -> std::task::RawWaker { std::task::RawWaker::new(p, &VTABLE) }
    static VTABLE: std::task::RawWakerVTable = std::task::RawWakerVTable::new(clone, noop, noop, noop);
    let waker = unsafe { std::task::Waker::from_raw(std::task::RawWaker::new(std::ptr::null(), &VTABLE)) };
    let mut cx = std::task::Context::from_waker(&waker);
    let mut fut = svc.call();
    if let std::task::Poll::Ready(val) = fut.as_mut().poll(&mut cx) {
        assert_eq!(val, 42);
    } else {
        panic!("future pending");
    }
}
